  if (context) parts.push('CONTEXT:\n' + context);
  if (target) parts.push('TARGET FILE: ' + target);
  parts.push('TASK:\n' + task);

  const messages = [
    { role: 'system', content: SYSTEM_PROMPT },
    { role: 'user', content: parts.join('\n\n') },
